; Play the game (USR 32768)
;
; The machine code's main loop, called from BASIC line 700 (to draw the city
; before "READY WHEN YOU ARE") and line 720 (to play). It runs GAME_FRAME,
; CHECK_RESCUED and CHECK_GAME_OVER over and over, returning to BASIC when 1 is
; pressed (back to the city gate, and "Have another go!") or when FRAMES_LEFT
; counts out.
;
; FRAMES_LEFT is both the stop signal and a frame budget. BASIC pokes 2 into it
; before the first call, so that call draws two frames and returns; it is then
; 0, and the next call decrements that to $FF, which means "run until the game
; says stop" -- CHECK_GAME_OVER and CHECK_RESCUED stop it by storing a small
; count again.
PLAY:
  DI
  LD HL,SPRITE_LIST_END   ; Mark the end of SPRITE_LIST, one byte past its
  LD (HL),$FF             ; eighth entry.
  CALL PRINT_COUNTERS     ; Print the grenade count and both energies on the
                          ; panel.
PLAY_0:
  LD BC,$F7FE             ; Key 1 (bit 0 of the 1-5 half-row, low when
  IN A,(C)                ; pressed)...
  BIT 0,A                 ;
  JR NZ,PLAY_1            ;
  EI                      ; ...goes straight back to BASIC.
  RET                     ;
PLAY_1:
  CALL GAME_FRAME         ; One frame of the game: move everything, draw the
                          ; view.
  CALL CHECK_RESCUED      ; Have both left the city?
  CALL CHECK_GAME_OVER    ; Out of time, or out of energy?
  LD A,(FRAMES_LEFT)      ; $FF: keep playing.
  CP $FF                  ;
  JP Z,PLAY_0             ;
  DEC A                   ; Otherwise count a frame off, and stop at zero.
  LD (FRAMES_LEFT),A      ;
  JP NZ,PLAY_0            ;
  LD A,(RANDOM_BITS)      ; Leave the random number in SEED, for BASIC's RND.
  LD (SEED),A             ;
  EI
  RET

; Signature
;
; "SandyWhite1983" twice, with a leading fragment and $7F between the copies,
; padded out to the next routine. Nothing reads it. There is another copy at
; L8448.
L8034:
  DEFM "dyWhite1983"      ; The tail of a third copy
  DEFB $7F
  DEFM "SandyWhite1983"
  DEFB $7F
  DEFM "SandyWhite1983"
  DEFB $FF,$FF,$FF

; Read the movement keys into the player's record
;
; Used by the routine at MOVE_PLAYER.
;
; V (move) and C (jump) become bits 2 and 1 of the flags at +7, in one go.
; SYMBOL SHIFT and M turn the player, but only when not stunned.
;
; IX The player's record
READ_CONTROLS:
  LD BC,$FEFE             ; CAPS SHIFT to V, made active high: C is bit 3, V
  IN A,(C)                ; bit 4.
  CPL                     ;
  AND $18                 ; Down to bits 1 and 2: jump and move.
  RRCA                    ;
  RRCA                    ;
  LD E,A                  ; Replace the player's jump and move bits with them.
  LD A,(IX+$07)           ;
  AND $F9                 ;
  OR E                    ;
  LD (IX+$07),A           ;
  LD A,(IX+$06)           ; Stunned: no turning.
  AND A                   ;
  RET NZ                  ;
  LD B,$7F                ; SPACE to B: SYMBOL SHIFT is bit 1, M bit 2.
  IN A,(C)                ;
  CPL                     ;
  AND $06                 ;
  CP $02                  ; SYMBOL SHIFT alone: turn one way...
  JR NZ,READ_CONTROLS_0   ;
  DEC (IX+$04)            ;
  RET                     ;
READ_CONTROLS_0:
  CP $04                  ; ...M alone: the other.
  JR NZ,READ_CONTROLS_1   ;
  INC (IX+$04)            ;
READ_CONTROLS_1:
  RET

; Return the key being pressed (USR 32912)
;
; BASIC's "Girl or Boy (g/b)?" (line 610) reads its answer through this, taking
; 0 as boy and 6 as girl and asking again for anything else.
;
; O:BC The key code the ROM's KEY-SCAN leaves in E
GET_KEY:
  CALL $028E              ; KEY-SCAN.
  LD B,$00                ; USR returns BC.
  LD C,E                  ;
  RET

; Wait for a key (USR 32919)
;
; Loops on the ROM's KEY-SCAN until it reports a key. BASIC calls it for every
; "press any key" pause.
WAIT_KEY:
  CALL $028E              ; KEY-SCAN.
  LD A,$FF                ; E is $FF while no key is down.
  CP E                    ;
  JR Z,WAIT_KEY           ;
  RET

; Draw one sprite into the render buffer
;
; Used by the routine at DRAW_HERE.
;
; A sprite frame is 64 bytes: 16 rows of mask, graphic, mask, graphic. Frame f
; lives 64f bytes above PLAY, so the frame number is the address, less PLAY,
; divided by 64 -- the sprites are at SPRITES (frames $68-$7F) and MORE_SPRITES
; (frames $DC-$FF).
;
; IX The frame byte of the sprite's entry in SPRITE_LIST; moved on one
; HL The sprite's place in PLANES
; DE The render buffer's row length less one ($1F)
DRAW_SPRITE:
  PUSH BC                 ; BC = the row step.
  LD C,E                  ;
  LD B,D                  ;
  LD A,(IX+$00)           ; The frame number.
  INC IX                  ;
  LD E,$00                ; DE = 64 x the frame number: the frame's first byte.
  RRA                     ;
  RR E                    ;
  RRA                     ;
  RR E                    ;
  AND $3F                 ;
  ADD A,$80               ;
  LD D,A                  ;
  CALL PLANE_TO_BUFFER    ; HL = where the sprite goes in the render buffer.
  LD A,$10                ; Sixteen rows.
DRAW_SPRITE_0:
  PUSH AF                 ;
  EX DE,HL                ; The left byte: mask out, then OR in the graphic...
  LD A,(DE)               ;
  AND (HL)                ;
  INC HL                  ;
  OR (HL)                 ;
  INC HL                  ;
  LD (DE),A               ;
  INC E                   ; ...and the right byte.
  LD A,(DE)               ;
  AND (HL)                ;
  INC HL                  ;
  OR (HL)                 ;
  INC HL                  ;
  LD (DE),A               ;
  EX DE,HL                ; Down a row.
  ADD HL,BC               ;
  POP AF
  DEC A
  JR NZ,DRAW_SPRITE_0
  LD E,C                  ; Give DE back.
  LD D,B                  ;
  POP BC                  ;
  RET

; Move the five ants
;
; Used by the routine at GAME_FRAME.
;
; Each ant takes its turn (ANT_TURN) chasing the player, whom IY points at.
MOVE_ANTS:
  LD IX,ANT1
  LD IY,PLAYER
  CALL ANT_TURN
  LD IX,ANT2
  LD IY,PLAYER
  CALL ANT_TURN
  LD IX,ANT3
  CALL ANT_TURN
  LD IX,ANT4
  CALL ANT_TURN
  LD IX,ANT5
  CALL ANT_TURN
  RET

; Unused
;
; $FF filler, like almost every gap between the routines, which start on
; 16-byte boundaries where they can.
L80FF:
  DEFB $FF

; Copy the render buffer to the screen
;
; Used by the routine at DRAW_VIEW.
;
; Rows 12-127 of the render buffer go to screen lines 12-127, bytes 1-30 of
; each: the rows above and below and the columns either side are margins for
; blocks and sprites to overhang into. Checked by filling the buffer's rows
; with their own numbers and running this.
COPY_TO_SCREEN:
  LD HL,RENDER_BUFFER+$0180 ; From row 12 of the buffer to line 12 of the
  LD DE,$4421               ; screen, column 1, in two passes (the top two
  LD B,$00                  ; thirds of the screen).
  LD A,$02                  ;
COPY_TO_SCREEN_0:
  PUSH AF                 ; Save the pass count; start the first row.
  JR COPY_TO_SCREEN_2     ;
COPY_TO_SCREEN_1:
  LD C,$E2                ; The next screen line: 256 bytes on from the start
  EX DE,HL                ; of the last, less the 30 just copied.
  ADD HL,BC               ;
  EX DE,HL                ;
COPY_TO_SCREEN_2:
  LD C,$1E                ; Skip the buffer's margin column, copy 30 bytes...
  INC HL                  ;
  LDIR                    ;
  INC HL                  ; ...and skip the other margin column.
  LD A,L                  ; Until the buffer crosses into its next 256 bytes:
  AND $E0                 ; eight rows, the first time four.
  JR NZ,COPY_TO_SCREEN_1  ;
  INC DE                  ; The next character row of the screen; every 64 rows
  INC DE                  ; of the buffer, the end of a pass.
  LD A,H                  ;
  AND $07                 ;
  JR Z,COPY_TO_SCREEN_3   ;
  LD A,D                  ;
  ADD A,$F9               ;
  LD D,A                  ;
  JR COPY_TO_SCREEN_2     ;
COPY_TO_SCREEN_3:
  POP AF                  ; Next pass.
  DEC A                   ;
  JR NZ,COPY_TO_SCREEN_0  ;
  RET

; Unused
L812F:
  DEFB $FF

; Convert a place in PLANES to an address in the render buffer
;
; Used by the routines at DRAW_SPRITE, DRAW_BLOCK and DRAW_BLOCK_TURNED.
;
; The 512 places in PLANES are 32 to a row, and each row is two half-rows of
; 16. The first half-row's places are every other byte across one row of the
; buffer; the second's are one byte across and four rows down. Each row of
; places is eight rows of the buffer. So the places tile the view like bricks,
; 16 pixels wide. Measured by running this for a range of places.
;
; HL On entry, an address in PLANES; on exit, the render buffer address of the
;    top left of what is drawn there
PLANE_TO_BUFFER:
  LD A,L
  RLA
  RL H
  RLA
  RL H
  RLA
  RL H
  RLCA
  RL L
  RL L
  RRA
  LD A,L
  RRA
  AND $9F
  LD L,A
  LD A,H
  SUB $08
  LD H,A
  RET

; Unused
L814A:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF,$FF,$FF,$FF

; Fill PLANES with $FF (nothing)
;
; Used by the routine at BUILD_PLANES.
CLEAR_PLANES:
  LD BC,$40FF             ; 64 times 8 bytes of $FF.
  LD HL,PLANES            ;
CLEAR_PLANES_0:
  LD (HL),C
  INC L
  LD (HL),C
  INC L
  LD (HL),C
  INC L
  LD (HL),C
  INC L
  LD (HL),C
  INC L
  LD (HL),C
  INC L
  LD (HL),C
  INC L
  LD (HL),C
  INC HL
  DJNZ CLEAR_PLANES_0
  RET

; Unused
L8179:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF

; Mark one height's blocks in PLANES
;
; Used by the routine at BUILD_PLANES.
;
; For each of the 512 places in PLANES, write the height's bit there if the
; gathered cell at the same offset from DE has a block at that height. Called
; for the heights in order, lowest first, so a higher block overwrites a lower
; one.
;
; C The height's bit ($01 for the ground layer up to $20)
; DE Where in VIEW_CELLS that height's cells start
MARK_PLANE:
  LD B,$80                ; 128 times four places.
  LD HL,PLANES            ;
MARK_PLANE_0:
  LD A,(DE)               ; A block at this height in the cell: mark the place.
  AND C                   ;
  JR Z,MARK_PLANE_1       ;
  LD (HL),C               ;
MARK_PLANE_1:
  INC L
  INC E
  LD A,(DE)
  AND C
  JR Z,MARK_PLANE_2
  LD (HL),C
MARK_PLANE_2:
  INC L
  INC E
  LD A,(DE)
  AND C
  JR Z,MARK_PLANE_3
  LD (HL),C
MARK_PLANE_3:
  INC L
  INC E
  LD A,(DE)
  AND C
  JR Z,MARK_PLANE_4
  LD (HL),C
MARK_PLANE_4:
  INC HL
  INC DE
  DJNZ MARK_PLANE_0
  RET

; Unused
L81A4:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF,$FF

; Sort the gathered cells into PLANES, height by height
;
; Used by the routine at DRAW_VIEW.
;
; Each height reads VIEW_CELLS one row of 32 cells further on: a block one
; higher is drawn one row further up the screen, so it covers the place a row
; back. That is the whole of the 3D -- after this, PLANES says, for each place
; in the view, which height of block (if any) is the one to be seen there.
BUILD_PLANES:
  CALL CLEAR_PLANES       ; Start from nothing.
  LD C,$01                ; The ground layer...
  LD DE,VIEW_CELLS        ;
  CALL MARK_PLANE         ;
  LD C,$02
  LD DE,VIEW_CELLS+$20
  CALL MARK_PLANE
  LD C,$04
  LD DE,VIEW_CELLS+$40
  CALL MARK_PLANE
  LD C,$08
  LD DE,VIEW_CELLS+$60
  CALL MARK_PLANE
  LD C,$10
  LD DE,VIEW_CELLS+$80
  CALL MARK_PLANE
  LD C,$20                ; ...up to height 5, 32 cells further on each time.
  LD DE,VIEW_CELLS+$A0    ;
  CALL MARK_PLANE         ;
  RET

; Print the grenade count and both energies
;
; Used by the routine at PLAY.
;
; Scripts 4, 8 and 11 print AMMO, the player's energy and the other's.
PRINT_COUNTERS:
  LD A,$04
  CALL PLAY_SCRIPT
  LD A,$08
  CALL PLAY_SCRIPT
  LD A,$0B
  CALL PLAY_SCRIPT
  RET

; Unused
;
; $FF filler, and in its last three bytes LD DE,31: the first instruction of
; DRAW_BLOCK, which is entered three bytes in because DRAW_SCENE has already
; set DE.
L81F4:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF,$FF,$11,$1F,$00

; Draw a block (views 0 and 2)
;
; One block's picture, drawn straight into the render buffer as immediate data,
; 16 pixels wide. Each of the eight steps paints one row of the block's outline
; -- the two bytes' edge pixels merged with what is behind them -- and the row
; eight below it outright, in the dithered shades of the faces. There is one of
; these for each pair of views, since turning the view round a quarter mirrors
; the shading: DRAW_BLOCK_TURNED is the other. SELECT_BLOCK_DRAWER points IY at
; the right one and DRAW_SCENE jumps to it.
;
; Ends by jumping back into DRAW_SCENE rather than returning.
;
; HL The block's place in PLANES
; DE The row length less one ($1F)
DRAW_BLOCK:
  CALL PLANE_TO_BUFFER    ; HL = the top left of the block in the render
                          ; buffer.
  LD A,(HL)               ; The first step: the outline row, and the solid row
  OR $01                  ; eight below...
  LD (HL),A               ;
  INC H                   ;
  LD (HL),$AA             ;
  INC L                   ;
  LD (HL),$BB             ;
  DEC H                   ;
  LD A,(HL)               ;
  AND $7F                 ;
  LD (HL),A               ;
  ADD HL,DE               ;
  LD A,(HL)               ; ...and so on down.
  AND $F8                 ;
  OR $04                  ;
  LD (HL),A               ;
  INC H                   ;
  LD (HL),$55             ;
  INC L                   ;
  LD (HL),$EE             ;
  DEC H                   ;
  LD A,(HL)               ;
  AND $1F                 ;
  OR $40                  ;
  LD (HL),A               ;
  ADD HL,DE               ;
  LD A,(HL)
  AND $E0
  OR $11
  LD (HL),A
  INC H
  LD (HL),$AA
  INC L
  LD (HL),$BB
  DEC H
  LD A,(HL)
  AND $07
  OR $10
  LD (HL),A
  ADD HL,DE
  LD A,(HL)
  AND $80
  OR $44
  LD (HL),A
  INC H
  LD (HL),$55
  INC L
  LD (HL),$EE
  DEC H
  LD A,(HL)
  AND $01
  OR $44
  LD (HL),A
  ADD HL,DE
  LD (HL),$91
  INC H
  LD A,(HL)
  AND $80
  OR $2A
  LD (HL),A
  INC L
  LD A,(HL)
  AND $01
  OR $BA
  LD (HL),A
  DEC H
  LD (HL),$11
  ADD HL,DE
  LD (HL),$44
  INC H
  LD A,(HL)
  AND $E0
  OR $15
  LD (HL),A
  INC L
  LD A,(HL)
  AND $07
  OR $E8
  LD (HL),A
  DEC H
  LD (HL),$46
  ADD HL,DE
  LD (HL),$A9
  INC H
  LD A,(HL)
  AND $F8
  OR $02
  LD (HL),A
  INC L
  LD A,(HL)
  AND $1F
  OR $A0
  LD (HL),A
  DEC H
  LD (HL),$1B
  ADD HL,DE
  LD (HL),$54
  INC H
  LD A,(HL)
  OR $01
  LD (HL),A
  INC L
  LD A,(HL)
  OR $80
  LD (HL),A
  DEC H
  LD (HL),$6E
  JP BLOCK_DRAWN          ; Back to DRAW_SCENE.

; Put IX where IY is, facing the same way
;
; Used by the routine at THROW_GRENADE.
;
; THROW_GRENADE uses this to start the grenade at the player.
COPY_POSITION:
  LD A,(IY+$04)
  LD (IX+$04),A
  LD A,(IY+$00)
  LD (IX+$00),A
  LD A,(IY+$01)
  LD (IX+$01),A
  LD A,(IY+$02)
  LD (IX+$02),A
  RET

; Unused
L82B9:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF

; Move the player
;
; Used by the routine at GAME_FRAME.
;
; IY is the person to be rescued, whom the player may stand on (bit 0 of the
; flags).
MOVE_PLAYER:
  LD IX,PLAYER
  LD IY,RESCUEE
  CALL READ_CONTROLS      ; Keys into the flags.
  CALL MOVE_OR_RESPAWN    ; Move.
  CALL CHOOSE_FRAME       ; Pick the animation frame.
  RET                     ;

; Unused
L82D2:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF,$FF,$FF,$FF

; Show the explosion while the explosion countdown runs
;
; Used by the routines at MOVE_GRENADE and ANT_TURN.
;
; Frames $F4-$F7, chosen by the low two bits of the count.
BLAST_FRAME:
  LD A,(IX+$09)
  AND A
  RET Z
  AND $03
  ADD A,$F4
  LD (IX+$08),A
  RET

; Unused
L82ED:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF

; Clear every fourth row of the render buffer
;
; Used by the routine at DRAW_VIEW.
;
; Unrolled: 29 rows of 32 bytes, four rows apart, from row 12 of the render
; buffer. CLEAR_PHASE moves the starting row on each call, so DRAW_VIEW's four
; calls clear rows 12-127 -- the rows COPY_TO_SCREEN copies to the screen.
CLEAR_BUFFER_ROWS:
  LD DE,$0061             ; The step to four rows on, the render buffer, 29
  LD H,$A1                ; rows of zeros.
  LD BC,$1D00             ;
  LD A,(CLEAR_PHASE)      ; Next quarter: rows 12, 13, 14 or 15 to start from.
  ADD A,$20               ;
  AND $60                 ;
  LD (CLEAR_PHASE),A      ;
  ADD A,$80               ;
  LD L,A                  ;
CLEAR_BUFFER_ROWS_0:
  LD (HL),C               ; 32 bytes.
  INC L                   ;
