; Read one cell of the city map
;
; Used by the routines at GATHER_VIEW0, GATHER_VIEW1, GATHER_VIEW2 and
; GATHER_VIEW3.
;
; The map is 128 x 128 bytes at CITY_MAP, a bit for each of six heights.
; Coordinates run $80-$FF; below that is outside the walls and reads as empty.
; Cell (x, y) is at CITY_MAP + 128(y - $80) + (x - $80).
;
; E x
; D y
; IX Where to write the byte; moved on one
READ_MAP_CELL:
  LD H,D                  ; Outside the walls if either coordinate is below
  BIT 7,H                 ; $80.
  JR Z,READ_MAP_CELL_0    ;
  LD A,E                  ;
  RLA                     ;
  JR NC,READ_MAP_CELL_0   ;
  RR H                    ; HL = CITY_MAP + 128 x (y AND $7F) + (x AND $7F).
  RRA                     ;
  LD L,A                  ;
  LD A,(HL)               ; Store the cell.
  LD (IX+$00),A           ;
  INC IX                  ;
  RET                     ;
READ_MAP_CELL_0:
  XOR A                   ; Outside: store 0.
  LD (IX+$00),A           ;
  INC IX                  ;
  RET                     ;

