; Gather the cells in view into VIEW_CELLS
;
; Used by the routine at DRAW_VIEW.
;
; Jumps to one of four routines, 32 bytes apart from GATHER_VIEW0, which read
; the map along diagonals in the order that view needs: 21 rows of two 16-cell
; half-rows, from VIEW_ORIGIN.
GATHER_VIEW:
