; Scroll the view when the player nears its edge
;
; Used by the routine at DRAW_VIEW.
;
; Reads where the player was placed this frame (the last entry of SPRITE_LIST)
; and, if that is outside a central window of the view, steps VIEW_ORIGIN a
; cell in the direction the player is facing -- unless the player is jumping or
; falling. It takes effect next frame, since the view has already been
; gathered.
SCROLL_VIEW:
  LD DE,(PLAYER_SPRITE)   ; Off the view altogether: leave it.
  LD A,D                  ;
  INC A                   ;
  RET Z                   ;
  DEC DE                  ; Undo the +1 PROJECT_SPRITES adds.
  LD A,E                  ; Across: inside if the column is 4-11 of 16...
  SUB $04                 ;
  AND $0F                 ;
  CP $08                  ;
  JR NC,SCROLL_VIEW_0     ;
  LD A,E                  ; ...and down: inside if the row is 8-23 of 32.
  RR D                    ;
  RRA                     ;
  RRA                     ;
  RRA                     ;
  RRA                     ;
  SUB $08                 ;
  AND $1F                 ;
  CP $10                  ;
  RET C                   ;
SCROLL_VIEW_0:
  LD HL,(VIEW_ORIGIN)     ; Outside: move the view.
  LD A,(PLAYER_FLAGS)     ; Not while jumping or falling.
  BIT 1,A                 ;
  RET NZ                  ;
  LD A,(PLAYER_FALL)      ;
  AND A                   ;
  RET NZ                  ;
  LD A,(PLAYER_FACING)    ; A cell the way the player faces.
  CALL STEP               ;
  LD (VIEW_ORIGIN),HL     ;
  RET

