; Draw the view
;
; Used by the routine at GAME_FRAME.
;
; A painter's algorithm in eleven steps: gather the map, sort it into PLANES by
; height, clear the render buffer, work out where each object falls in PLANES,
; scroll if the player is near the edge, sort the objects by that, turn their
; places into distances, pick the block picture for this view, paint the lot
; back to front, and copy it to the screen.
DRAW_VIEW:
  CALL GATHER_VIEW        ; The map, into VIEW_CELLS.
  CALL BUILD_PLANES       ; Into PLANES, by height.
  CALL CLEAR_BUFFER_ROWS  ; Clear the visible rows of the render buffer, a
  CALL CLEAR_BUFFER_ROWS  ; quarter at a time.
  CALL CLEAR_BUFFER_ROWS  ;
  CALL CLEAR_BUFFER_ROWS  ;
  CALL PROJECT_SPRITES    ; Where each object falls.
  CALL SCROLL_VIEW        ; Scroll next frame, if need be.
  CALL SORT_SPRITES       ; Sort the objects...
  CALL SPRITE_DISTANCES   ; ...and space them out.
  CALL SELECT_BLOCK_DRAWER ; The block picture for this view.
  CALL DRAW_SCENE         ; Paint.
  CALL COPY_TO_SCREEN     ; Show.
  RET                     ;

