; The rescued person and the player in one cell: nobody falls
;
; Used by the routine at MOVE_RESCUEE.
;
; When the two are in the same cell and at most one block apart in height --
; one on the other's head -- the rescued person's stun and the player's stun
; and fall count are cleared. So dropping onto each other is never a landing:
; seen in play, when a scene dropped the player three blocks onto the rescued
; person's head and it made no bad fall and no search for an ant beneath.
;
; IX The person being rescued
; IY The player
SHARE_CELL:
  LD A,(IX+$02)           ; More than a block apart in height: nothing.
  SUB (IY+$02)            ;
  JP P,SHARE_CELL_0       ;
  CPL                     ;
  INC A                   ;
SHARE_CELL_0:
  CP $02                  ;
  RET NC                  ;
  LD A,(IX+$00)           ; Not the same cell: nothing.
  CP (IY+$00)             ;
  RET NZ                  ;
  LD A,(IX+$01)           ;
  CP (IY+$01)             ;
  RET NZ                  ;
  XOR A                   ; Clear both stuns and the player's fall.
  LD (IX+$06),A           ;
  LD (IY+$06),A           ;
  LD (IY+$05),A           ;
  NOP                     ; Three NOPs, left where something was taken out.
  NOP                     ;
  NOP                     ;
  RET

