; Paint PLANES and the sprites into the render buffer, back to front
;
; Used by the routine at DRAW_VIEW.
;
; PLANES holds, per place, one of $01, $02 ... $20 (a block at that height) or
; $FF (nothing). This paints every $01 place, then every $02, and so on up to
; $40 -- a pass with no blocks in it, for anything standing on top of a
; six-high block -- using CPIR to find each next one. The sprites are threaded
; in by distance: BC counts down the places to the next sprite across all the
; passes, so when CPIR runs BC out before finding a block, it is time to draw a
; sprite (DRAW_HERE).
DRAW_SCENE:
  LD IX,SPRITE_LIST       ; BC = the count to the first sprite.
  CALL NEXT_SPRITE        ;
  LD DE,$001F             ; Row step for the drawers; start with height bit
  LD A,$01                ; $01.
  LD HL,PLANES+$01FF      ;
  JR DRAW_SCENE_1
; This entry point is used by the routine at DRAW_HERE.
DRAW_SCENE_0:
  EX AF,AF'               ; The next height's bit; past $40, done.
  RLCA                    ;
  CP $80                  ;
  RET Z                   ;
  DEC HL                  ; HL was one past the end; back to the last place.
DRAW_SCENE_1:
  LD (HL),A               ; A sentinel, so the CPIR stops at the end.
  LD HL,PLANES            ; From the first place.
; This entry point is used by the routines at BLOCK_DRAWN and DRAW_HERE.
DRAW_SCENE_2:
  CPIR                    ; Find the next place at this height -- or run out of
  JP PO,DRAW_HERE         ; count first.
  EX AF,AF'               ; Found the sentinel: the next height.
  LD A,H                  ;
  CP $B7                  ;
  JR Z,DRAW_SCENE_0       ;
  PUSH HL                 ; Draw the block through the pointer
  DEC HL                  ; SELECT_BLOCK_DRAWER set.
  JP (IY)                 ;
  NOP

; Where DRAW_BLOCK and DRAW_BLOCK_TURNED come back to
;
; Used by the routines at DRAW_BLOCK and DRAW_BLOCK_TURNED.
BLOCK_DRAWN:
  POP HL                  ; Carry on scanning.
  EX AF,AF'               ;
  JR DRAW_SCENE_2         ;

; Draw the sprite that is due, then carry on the scan
;
; Used by the routine at DRAW_SCENE.
DRAW_HERE:
  EX AF,AF'               ; The place is the one before where CPIR stopped.
  PUSH HL                 ;
  DEC HL                  ;
  CALL DRAW_SPRITE        ;
  POP HL
  CALL NEXT_SPRITE        ; The next sprite's count.
  LD A,H                  ; The scan ran to the end: next height.
  CP $B7                  ;
  JR Z,DRAW_SCENE_0       ;
  EX AF,AF'
  JR DRAW_SCENE_2

