; Load the count to the next sprite in SPRITE_LIST
;
; Used by the routines at DRAW_SCENE and DRAW_HERE.
;
; Skips entries whose count is zero.
;
;   IX An entry in SPRITE_LIST; on exit, its frame byte
; O:BC The count
NEXT_SPRITE:
  LD C,(IX+$00)
  INC IX
  LD B,(IX+$00)
  INC IX
  LD A,C
  OR B
  RET NZ
  INC IX                  ; Skip the frame byte of an empty entry.
  JR NEXT_SPRITE          ;

