; Sort SPRITE_LIST by place in PLANES
;
; Used by the routine at DRAW_VIEW.
;
; A bubble sort into ascending order, repeated until a pass swaps nothing.
SORT_SPRITES:
  LD C,$00                ; C = 0: nothing swapped.
SORT_SPRITES_0:
  LD B,$07                ; Seven comparisons a pass.
  LD IX,SPRITE_LIST       ;
SORT_SPRITES_1:
  LD L,(IX+$00)           ; This entry's place against the next's.
  LD H,(IX+$01)           ;
  LD E,(IX+$03)           ;
  LD D,(IX+$04)           ;
  LD A,D                  ;
  CP H                    ;
  JR NZ,SORT_SPRITES_2    ;
  LD A,E                  ;
  CP L                    ;
SORT_SPRITES_2:
  JR NC,SORT_SPRITES_3
  LD (IX+$00),E           ; Out of order: swap places and frames, and note it.
  LD (IX+$01),D           ;
  LD (IX+$03),L           ;
  LD (IX+$04),H           ;
  LD C,(IX+$02)           ;
  LD A,(IX+$05)           ;
  LD (IX+$02),A           ;
  LD (IX+$05),C           ;
  LD C,$01                ;
SORT_SPRITES_3:
  INC IX
  INC IX
  INC IX
  DJNZ SORT_SPRITES_1
  DEC C                   ; Swapped something: another pass.
  JR Z,SORT_SPRITES_0     ;
  RET

