; Work out where each object falls in PLANES
;
; Used by the routine at DRAW_VIEW.
;
; For each object, last to first, its position relative to VIEW_ORIGIN is
; turned for the view and projected: the half-row is v - u - 2h and the column
; (u + v) / 2, where u and v are the turned coordinates and h the height. The
; place is height x 512 + half-row x 16 + column -- the height counting a whole
; pass of DRAW_SCENE -- and it goes into SPRITE_LIST with the sprite frame: the
; object's first frame, plus four times its animation frame, plus its facing
; relative to the view.
PROJECT_SPRITES:
  LD IX,ANT5              ; From the fifth ant back to the player; eight
  LD DE,(VIEW_ORIGIN)     ; objects.
  LD A,$08                ;
  LD HL,SPRITE_LIST       ;
PROJECT_SPRITES_0:
  EX AF,AF'
  PUSH HL
  LD B,(IX+$02)           ; Its height.
  LD A,(IX+$00)           ; Its position relative to the view's origin.
  SUB E                   ;
  LD L,A                  ;
  LD A,(IX+$01)           ;
  SUB D                   ;
  LD H,A                  ;
  LD A,(VIEW)             ; Turn it for the view: swap x and y for views 1 and
  RRA                     ; 3, and negate as the view needs.
  JR NC,PROJECT_SPRITES_1 ;
  LD C,H                  ;
  LD H,L                  ;
  LD L,C                  ;
  RRA                     ;
  JR NC,PROJECT_SPRITES_2 ;
  XOR A                   ;
  SUB L                   ;
  LD L,A                  ;
  JR PROJECT_SPRITES_4    ;
PROJECT_SPRITES_1:
  RRA                     ;
  JR NC,PROJECT_SPRITES_3 ;
  XOR A                   ;
  SUB L                   ;
  LD L,A                  ;
PROJECT_SPRITES_2:
  XOR A                   ;
  SUB H                   ;
  LD H,A                  ;
PROJECT_SPRITES_3:
  LD A,L                  ; Raise it by its height.
PROJECT_SPRITES_4:
  ADD A,B                 ;
  LD L,A                  ;
  LD A,H                  ;
  SUB B                   ;
  LD H,A                  ;
  SUB L                   ; The half-row, 0-31, or out of view.
  JP PE,OFF_VIEW          ;
  CP $20                  ;
  JR NC,OFF_VIEW          ;
  RLCA                    ; Times 16, with the height above it.
  RLCA                    ;
  RLCA                    ;
  SLA A                   ;
  RL B                    ;
  LD C,A                  ;
  LD A,L                  ; The column, 0-31 before halving, or out of view.
  ADD A,H                 ;
  JP PE,OFF_VIEW          ;
  CP $20                  ;
  JR NC,OFF_VIEW          ;
  AND A                   ; Into the place, plus one.
  RRA                     ;
  OR C                    ;
  LD C,A                  ;
  INC BC                  ;
; This entry point is used by the routine at OFF_VIEW.
PROJECT_SPRITES_5:
  POP HL                  ; Store the place.
  LD (HL),C               ;
  INC HL                  ;
  LD (HL),B               ;
  INC HL                  ;
  LD A,(VIEW)             ; The facing relative to the view.
  ADD A,(IX+$04)          ;
  AND $03                 ;
  LD C,A                  ;
  LD A,(IX+$08)           ; Bit 7 set: the frame outright...
  AND A                   ;
  JP M,PROJECT_SPRITES_6  ;
