  RLCA                    ; animation frame, plus the facing.
  ADD A,(IX+$03)          ;
  ADD A,C                 ;
PROJECT_SPRITES_6:
  LD (HL),A
  INC HL
  LD BC,$FFF0             ; The object before.
  ADD IX,BC               ;
  EX AF,AF'
  DEC A
  JR NZ,PROJECT_SPRITES_0
  RET

