; See whether an exploding grenade got an ant
;
; Used by the routine at GRENADE_BLAST.
;
; Only ants at the grenade's height and not already exploding. Within four
; cells (counted along the grid, not diagonally) the ant is blown up -- "GOOD
; SHOT!" -- and within seven it is stunned for 24 frames. Both seen in play, in
; staged scenes.
;
; HL The grenade's x and y
; C Its height
; IY The ant
BLAST_ANT:
  LD A,(IY+$02)           ; Another height, or already exploding: no.
  CP C                    ;
  RET NZ                  ;
  LD A,(IY+$09)           ;
  AND A                   ;
  RET NZ                  ;
  LD E,(IY+$00)
  LD D,(IY+$01)
  CALL DISTANCE
  CP $08                  ; Eight or more away: missed.
  RET NC                  ;
  CP $05                  ; Five to seven: stunned.
  JR C,BLAST_ANT_0        ;
  LD (IY+$06),$18         ;
  RET                     ;
BLAST_ANT_0:
  LD (IY+$09),$05         ; Four or less: blown up...
  LD (IY+$06),$00         ;
  LD A,(GRENADE_EVENTS)   ; ...and "GOOD SHOT!".
  OR $04                  ;
  LD (GRENADE_EVENTS),A   ;
  RET

