; Move an object one frame: fall, climb, jump, walk
;
; Used by the routine at MOVE_OR_RESPAWN.
;
; The physics for everything. Nothing is solid but the map, and ants put
; themselves in the map (TOGGLE_MAP_BIT), so walking into an ant is walking
; into a wall -- and an ant arriving in someone's cell is a bite.
;
; IX The object
MOVE_OBJECT:
  LD L,(IX+$00)           ; Where it is.
  LD H,(IX+$01)           ;
  LD C,(IX+$02)           ;
  LD D,H                  ; Anything to stand on? If not, fall.
  LD E,L                  ;
  LD A,C                  ;
  DEC A                   ;
  CALL TEST_BELOW         ;
  JP NC,FALL              ;
; This entry point is used by the routine at FALL.
MOVE_OBJECT_0:
  LD D,H                  ; Something in this very cell: bitten, and pushed up.
  LD E,L                  ;
  LD A,C                  ;
  CALL TEST_MAP_BIT       ;
  JP C,BITTEN             ;
  LD A,(IX+$06)           ; Stunned: count it down.
  AND A                   ;
  JP NZ,STUNNED           ;
  LD A,(IX+$05)           ; Just landed from a fall.
  CP $02                  ;
  JP NC,LANDED            ;
  XOR A                   ; Standing.
  LD (IX+$05),A           ;
  BIT 1,(IX+$07)          ; Jump.
  JP NZ,RISE              ;
; This entry point is used by the routines at FALL and RISE.
MOVE_OBJECT_1:
  BIT 2,(IX+$07)          ; Walk forward, if moving...
  JP Z,MOVE_OBJECT_2      ;
  LD A,(IX+$04)           ; ...a cell the way it faces...
  CALL STEP               ;
  LD D,H                  ;
  LD E,L                  ;
  LD A,C                  ;
  CALL TEST_MAP_BIT       ;
  JP C,STEP_UP            ; ...unless the way is blocked.
  LD (IX+$00),L           ; A step.
  LD (IX+$01),H           ;
  LD (IX+$0F),$01         ;
MOVE_OBJECT_2:
  RET

; Unused
L8857:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF

; Land from a fall
;
; Used by the routine at MOVE_OBJECT.
;
; A fall of five frames or more stuns for eight frames each, and is a bad fall;
; shorter ones stun for as many frames as they lasted and are a step. Landing
; at height 1 means landing on something on the ground, which may be an ant
; (PARALYSE_ANT). Seen in play: a drop of five blocks stunned the player for 48
; frames with a bad fall.
;
; A Frames spent falling, at least 2
LANDED:
  LD C,$01                ; A step...
  CP $05                  ;
  JR C,LANDED_0           ;
  RLCA                    ; ...or, from five frames up, a bad fall, stunned for
  RLCA                    ; eight times as long.
  RLCA                    ;
  LD C,$02                ;
  LD (IX+$05),$00         ;
LANDED_0:
  LD (IX+$06),A           ; The stun and the event.
  LD (IX+$0F),C           ;
  LD A,(IX+$02)           ; On something at ground level: an ant?
  CP $01                  ;
  RET NZ                  ;
  CALL PARALYSE_ANT       ;
  RET

; Unused
L887F:
  DEFB $FF

; Fall, after a frame's grace
;
; Used by the routine at MOVE_OBJECT.
;
; On the first frame with nothing underneath, an object can still walk -- off a
; ledge, say -- and only after that does it drop a block a frame.
;
; Nothing sets bit 3 of the flags -- not the BASIC's DATA, not the code -- so
; the three instructions of its "never falls" branch never run. These are the
; only instructions in the game not seen to run.
FALL:
  BIT 3,(IX+$07)          ; Bit 3: never falls.
  JR Z,FALL_0             ;
  XOR A                   ;
  LD (IX+$05),A           ;
  JP MOVE_OBJECT_0        ;
FALL_0:
  LD A,(IX+$05)           ; Count the frame; the first one, walk.
  INC A                   ;
  LD (IX+$05),A           ;
  DEC A                   ;
  JP Z,MOVE_OBJECT_1      ;
  DEC C                   ; Then drop a block.
  LD (IX+$02),C           ;
  RET

; Unused
L889D:
  DEFB $FF,$FF,$FF

; Something is in this cell: a bite
;
; Used by the routine at MOVE_OBJECT.
;
; And the object is pushed up a block, out of the way.
BITTEN:
  LD (IX+$0F),$04
  JP RISE

; Unused
L88A7:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF

; Count down being stunned
;
; Used by the routine at MOVE_OBJECT.
;
; Also clears the fall count, so a fall that ends while an object is still
; stunned is never landed: no stun, no bad fall. The rescued person starts each
; level stunned for four frames (line 120's DATA), which is enough to swallow a
; short drop.
STUNNED:
  DEC A
  LD (IX+$06),A
  XOR A
  LD (IX+$05),A
  RET

