  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF

; The rescued person shares the player's cell
;
; Used by the routine at FOLLOW_PLAYER.
;
; Only FOLLOW_PLAYER comes here, when the distance between the two is 0: one is
; standing on the other. If the rescued person is the higher of the two they
; take the player's facing and walk on; if lower, they stop. Both seen in play,
; in staged scenes.
;
;   IX The rescued person
;   IY The player
; O:C The player's facing
ON_TOP:
  LD C,(IY+$04)
  LD A,(IX+$02)
  NOP                     ; A NOP, left where something was taken out.
  CP (IY+$02)             ;
  RET NC                  ;
  RES 2,(IX+$07)          ;
  RET                     ;

; Go up a block, if there is room
;
; Used by the routines at MOVE_OBJECT and BITTEN.
RISE:
  LD D,H                  ; Blocked above: walk instead.
  LD E,L                  ;
  LD A,C                  ;
  INC A                   ;
  CALL TEST_MAP_BIT       ;
  JP C,MOVE_OBJECT_1      ;
  INC C
  LD (IX+$02),C
  RET

; Unused
L88DF:
  DEFB $FF

; Blocked: step up onto it, for things that can
;
; Used by the routine at MOVE_OBJECT.
;
; Only with bit 4 of the flags -- the rescued person and the grenade -- and
; only if the cell above the object is free. It rises there, and next frame
; walks on at the new height.
STEP_UP:
  BIT 4,(IX+$07)
  RET Z
  LD E,(IX+$00)
  LD D,(IX+$01)
  INC C
  LD A,C
  CALL TEST_MAP_BIT
  RET C
  LD (IX+$02),C
  RET

