L88F5:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF

; Move a position one cell in a direction
;
; Used by the routines at SCROLL_VIEW, MOVE_OBJECT and FOLLOW_PLAYER.
;
; A The direction (only bits 0-1 count)
; HL The position: L is x, H is y
STEP:
  AND $03
  JR Z,STEP_2
  CP $01
  JR Z,STEP_1
  CP $02
  JR Z,STEP_0
  DEC L                   ; 3: x down.
  RET                     ;
STEP_0:
  DEC H                   ; 2: y down.
  RET                     ;
STEP_1:
  INC L                   ; 1: x up.
  RET                     ;
STEP_2:
  INC H                   ; 0: y up.
  RET                     ;

