L8914:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF,$FF

; Is there a block at a height in a cell?
;
; Used by the routines at MOVE_OBJECT, RISE, STEP_UP and TEST_BELOW.
;
; Height 6 is the open sky, always empty; above it, always solid, and so is
; height -1 ($FF), which is how the ground holds things up. Anywhere outside
; the walls is empty.
;
;   A The height
;   DE The cell: E is x, D is y
; O:F Carry set if there is a block
TEST_MAP_BIT:
  CP $06
  JR NC,TEST_MAP_BIT_2
  INC A
  LD B,A
  BIT 7,D                 ; Outside the walls: empty.
  JR Z,TEST_MAP_BIT_1     ;
  LD A,E                  ;
  RLA                     ;
  RET NC                  ;
  RR D                    ; The cell's address.
  RRA                     ;
  LD E,A                  ;
  LD A,(DE)               ;
TEST_MAP_BIT_0:
  RRCA                    ; Rotate the height's bit into the carry.
  DJNZ TEST_MAP_BIT_0     ;
  RET
TEST_MAP_BIT_1:
  AND A
  RET
TEST_MAP_BIT_2:
  RET Z                   ; Heights 6 and up.
  CCF                     ;
  RET

; Unused
L893B:
  DEFB $FF,$FF,$FF,$FF,$FF

; Flip a height's bit in a map cell
;
; Used by the routine at MOVE_ANT.
;
; How the ants become solid: MOVE_ANT takes an ant out of the map before moving
; it and puts it back after, so everything else collides with it. This is why
; the city map changes during play. Nothing outside the walls is written.
;
; It is an XOR, so the map and the ant's record have to agree: an ant moved
; without its bit leaves a phantom block behind and puts one in its own cell,
; where it is promptly "bitten" and pushed up a block. Seen in a scene that did
; exactly that.
;
; A The height
; DE The cell: E is x, D is y
TOGGLE_MAP_BIT:
  CP $06
  RET NC
  INC A
  LD B,A
  BIT 7,D
  RET Z
  LD A,E
  RLA
  RET NC
  RR D
  RRA
  LD E,A
  LD A,$80
TOGGLE_MAP_BIT_0:
  RLCA
  DJNZ TOGGLE_MAP_BIT_0
  LD B,A
  LD A,(DE)
  XOR B
  LD (DE),A
  RET

; Unused
L8959:
  DEFB $FF,$FF,$FF,$FF

; Is there anything to stand on?
;
; Used by the routine at MOVE_OBJECT.
;
; As TEST_MAP_BIT, but an object with bit 0 of its flags set can also stand on
; the object IY points at: the player on the rescued person, and the other way
; about.
;
;   A The height to test
;   DE The cell
; O:F Carry set if something is there
TEST_BELOW:
  BIT 0,(IX+$07)
  JR Z,TEST_BELOW_1
  LD B,A
  CP (IY+$02)
  JR NZ,TEST_BELOW_1
  LD A,D
  CP (IY+$01)
  JR NZ,TEST_BELOW_0
  LD A,E
  CP (IY+$00)
  JR Z,TEST_BELOW_2
TEST_BELOW_0:
  LD A,B
TEST_BELOW_1:
  CALL TEST_MAP_BIT
  RET
TEST_BELOW_2:
  CCF
  RET

