  DEFB $FF,$FF,$FF,$FF

; Choose the animation frame
;
; Used by the routines at MOVE_PLAYER and MOVE_RESCUEE.
;
; The explosion while it lasts; then, stunned for five frames or more, frame 3
; (or 2 while still falling); stunned for less, 2; falling, 4; walking, 0 and 1
; in turn; standing, 0.
CHOOSE_FRAME:
  LD A,(IX+$09)
  AND A
  JR Z,CHOOSE_FRAME_0
  AND $03
  ADD A,$F4
  LD (IX+$08),A
  RET
CHOOSE_FRAME_0:
  LD A,(IX+$06)
  CP $05
  JR C,CHOOSE_FRAME_1
  LD A,(IX+$05)
  AND A
  JR NZ,CHOOSE_FRAME_2
  LD (IX+$08),$03
  RET
CHOOSE_FRAME_1:
  AND A
  JR Z,CHOOSE_FRAME_3
CHOOSE_FRAME_2:
  LD (IX+$08),$02
  RET
CHOOSE_FRAME_3:
