; Move an object, or count down its explosion and send it home
;
; Used by the routines at MOVE_PLAYER, MOVE_GRENADE, MOVE_ANT and MOVE_RESCUEE.
;
; While the explosion countdown runs the object does not move, and when it runs
; out the object goes back to its home position. The player starts every level
; this way: BASIC sets its countdown to 1, so the first frame puts it at the
; city gate.
MOVE_OR_RESPAWN:
  LD A,(IX+$09)
  AND A
  JR NZ,MOVE_OR_RESPAWN_0
  CALL MOVE_OBJECT
  RET
MOVE_OR_RESPAWN_0:
  DEC A
  LD (IX+$09),A
  RET NZ
  LD A,(IX+$0A)           ; Home.
  LD (IX+$00),A           ;
  LD A,(IX+$0B)           ;
  LD (IX+$01),A           ;
  LD A,(IX+$0C)           ;
  LD (IX+$02),A           ;
  XOR A                   ; Not falling, not stunned, standing.
  LD (IX+$05),A           ;
  LD (IX+$06),A           ;
  LD (IX+$08),A           ;
  RET

