  DEFB $FF,$FF,$FF,$FF

; Move an ant towards the player
;
; Used by the routine at ANT_TURN.
;
; The ant is taken out of the map, moved, and put back. If the move brought it
; closer to the player it walks on (and, within four cells, turns to face the
; player); otherwise it stops and turns a random way.
MOVE_ANT:
  LD D,(IX+$01)           ; Out of the map...
  LD E,(IX+$00)           ;
  PUSH DE                 ;
  LD A,(IX+$02)           ;
  CALL TOGGLE_MAP_BIT     ;
  CALL MOVE_OR_RESPAWN    ; Move it.
  LD H,(IX+$01)           ; ...and back in where it is now.
  LD L,(IX+$00)           ;
  LD D,H                  ;
  LD E,L                  ;
  LD A,(IX+$02)           ;
  CALL TOGGLE_MAP_BIT     ;
  LD D,(IY+$01)           ; Its distance from the player, now and before.
  LD E,(IY+$00)           ;
  CALL DISTANCE           ;
  LD C,A                  ;
  POP HL                  ;
  CALL DISTANCE           ;
  LD B,A                  ;
  LD A,C
  CP B
  JR NC,MOVE_ANT_0
  LD A,(IX+$08)           ; Closer: walk.
  INC A                   ;
  AND $01                 ;
  LD (IX+$08),A           ;
  LD A,C                  ; Within four: face the player.
  CP $04                  ;
  RET NC                  ;
  LD H,(IX+$01)           ;
  LD L,(IX+$00)           ;
  CALL DIRECTION_TO       ;
  LD (IX+$04),A           ;
  RET
MOVE_ANT_0:
  LD (IX+$08),$00         ; No closer: stop, and turn left or right at random.
  CALL RANDOM             ;
  JR C,MOVE_ANT_1         ;
  INC (IX+$04)            ;
  RET                     ;
MOVE_ANT_1:
  DEC (IX+$04)            ;
  RET                     ;

