  DEFB $FF,$FF

; Distance between two cells, along the grid
;
; Used by the routines at BLAST_ANT, MOVE_ANT, FOLLOW_PLAYER and MOVE_RESCUEE.
;
;   HL One cell
;   DE The other
; O:A |x difference| + |y difference|
DISTANCE:
  LD A,E
  SUB L
  JP P,DISTANCE_0
  CPL
  INC A
DISTANCE_0:
  LD B,A
  LD A,D
  SUB H
  JP P,DISTANCE_1
  CPL
  INC A
DISTANCE_1:
  ADD A,B
  RET

; The direction from one cell towards another
;
; Used by the routines at MOVE_ANT and FOLLOW_PLAYER.
;
; Straight along the axis if they share a row or column; otherwise one of the
; two directions that close the gap, chosen by the signs.
;
;   HL From
;   DE Towards
; O:A A direction for STEP (only the low two bits count)
DIRECTION_TO:
  LD A,H
  SUB D
  JR Z,DIRECTION_TO_1
  RLCA
  AND $01
  LD B,A
  LD A,L
  SUB E
  JR Z,DIRECTION_TO_0
  RLCA
  AND $01
  XOR B
  RLC B
  OR B
  CPL
  RET
DIRECTION_TO_0:
  LD A,B
  RLCA
  XOR $02
  RET
DIRECTION_TO_1:
  LD A,L
  SUB E
  JP P,DIRECTION_TO_2
  LD A,$01
  RET
DIRECTION_TO_2:
  LD A,$03
  RET

; Walk the rescued person after the player
;
; Used by the routine at MOVE_RESCUEE.
;
; Walks towards the player while two to five cells away, and stops beside them
; or more than five away. The facing is kept if one more step along it would
; still end beside the player; otherwise they turn towards the player.
FOLLOW_PLAYER:
  LD A,(IX+$06)           ; Not while stunned.
  AND A                   ;
  RET NZ                  ;
  LD E,(IY+$00)
  LD D,(IY+$01)
  LD L,(IX+$00)
  LD H,(IX+$01)
  LD C,(IX+$04)
  CALL DISTANCE
  SET 2,(IX+$07)          ; Walking, unless...
  CP $06                  ; ...six or more away, or beside the player.
  JR NC,FOLLOW_PLAYER_2   ;
  CP $01                  ;
  JR Z,FOLLOW_PLAYER_2    ;
  AND A                   ; In the player's own cell.
  JR NZ,FOLLOW_PLAYER_0   ;
  CALL ON_TOP             ;
FOLLOW_PLAYER_0:
  LD A,C                  ; Would a step this way end beside the player?
  CALL STEP               ;
  CALL DISTANCE           ;
  DEC A                   ;
  JR Z,FOLLOW_PLAYER_1    ;
  LD L,(IX+$00)           ; No: face the player.
  LD H,(IX+$01)           ;
  CALL DIRECTION_TO       ;
  LD C,A                  ;
FOLLOW_PLAYER_1:
  LD (IX+$04),C
  RET
FOLLOW_PLAYER_2:
  RES 2,(IX+$07)
  RET

