  LD (HL),A
  INC HL
  LD (HL),A
  INC HL
  INC HL
  INC HL
  DJNZ FILL_PLAY_ATTRIBUTES_0
  RET

; Unused
L8B46:
  DEFB $FF,$FF,$FF,$FF

; A burst of noise on the speaker
;
; Used by the routines at RUN_SCRIPT and HANDLE_EVENTS.
;
; B Length
NOISE:
  LD A,(BORDER)           ; The border colour, with the MIC and speaker bits
  AND $07                 ; set.
  OR $18                  ;
  LD C,A                  ;
NOISE_0:
  CALL RANDOM             ; A random speaker bit, each time round.
  AND $10                 ;
  XOR C                   ;
  OUT ($FE),A             ;
  DJNZ NOISE_0
  LD A,C
  OUT ($FE),A
  RET

; An unused script
;
; In the RUN_SCRIPT format -- AT 15,12, then letters between notes -- and
; spelling "OWCH!". It is not among the ones SCRIPTS counts from, so nothing
; ever runs it: a leftover.
L8B60:
  DEFB $16,$0F,$0C,$4F,$9F,$8F,$83,$8C
  DEFB $57,$81,$85,$9F,$83,$84,$43,$8A
  DEFB $8D,$8E,$FF,$83,$48,$81,$85,$8B
  DEFB $88,$21,$86,$84,$81,$00,$FF,$FF

; A note on the speaker
;
; Used by the routine at RUN_SCRIPT.
;
; A The note, an index into TONES
TONE:
  AND $1F                 ; HL = the note's entry.
  RLA                     ;
  ADD A,$B1               ;
  LD L,A                  ;
  LD H,$8B                ;
  LD A,(BORDER)           ; The border colour, with the MIC and speaker bits
  AND $07                 ; set.
  OR $18                  ;
  LD C,A                  ;
  LD E,(HL)               ; E = the pitch, B = the half-cycles.
  INC HL                  ;
  LD B,(HL)               ;
TONE_0:
  LD A,E                  ; The pitch delay...
TONE_1:
  DEC A                   ;
  JP NZ,TONE_1            ;
  NOP                     ;
  NOP                     ;
  NOP                     ;
  NOP                     ;
  NOP                     ;
  NOP                     ;
  NOP                     ;
  NOP                     ;
  NOP                     ;
  NOP                     ;
  LD A,C                  ; ...then flip the speaker.
  XOR $10                 ;
  LD C,A                  ;
  OUT ($FE),A             ;
  DEC B
  JP NZ,TONE_0
  AND $EF                 ; Speaker off.
  OUT ($FE),A             ;
  RET

; Note table
;
; A delay (the pitch) and a count of half-cycles per note: 16 notes rising in
; pitch, the count rising with them so that each lasts about as long. Note $0F
; is taken as noise by RUN_SCRIPT, so the last entry is never played.
TONES:
  DEFB $00,$25
  DEFB $F1,$27
  DEFB $E3,$29
  DEFB $D6,$2C
  DEFB $C9,$2F
  DEFB $BE,$31
  DEFB $B3,$34
  DEFB $A8,$38
  DEFB $9F,$3B
  DEFB $95,$3F
  DEFB $8D,$43
  DEFB $84,$47
  DEFB $7C,$4C
  DEFB $75,$50
  DEFB $6E,$56
  DEFB $68,$5B

; Paralyse the ant the player has landed on
;
; Used by the routine at LANDED.
;
; An ant that is not exploding and not already paralysed is paralysed for good,
; with "PARALYSED AN ANT !". Seen in play, by dropping the player on a stunned
; ant; and landing on a plain one-block wall finds no ant here and returns.
;
; HL The cell
PARALYSE_ANT:
  LD DE,$0010             ; Five ants.
  LD IY,ANT1              ;
  LD B,$05                ;
PARALYSE_ANT_0:
  LD A,(IY+$00)           ; Is this one in the cell?
  CP L                    ;
  JR NZ,PARALYSE_ANT_1    ;
  LD A,(IY+$01)           ;
  CP H                    ;
  JR Z,PARALYSE_ANT_2     ;
PARALYSE_ANT_1:
  ADD IY,DE
  DJNZ PARALYSE_ANT_0
  RET
PARALYSE_ANT_2:
  LD A,(IY+$09)           ; Not while exploding, and not twice.
  AND A                   ;
  RET NZ                  ;
  LD A,$FF                ;
  CP (IY+$06)             ;
  RET Z                   ;
  LD (IY+$06),A           ; Paralysed, for good.
  LD A,$10                ;
  CALL PLAY_SCRIPT        ;
  RET

; Unused
;
; A repeating 5-byte pattern -- 0E 00 3A 25 B4, which reads as LD C,0 and a LD
; A,(nn) -- filling the page. Nothing reads it.
L8BFF:
  DEFB $FF,$0E,$00,$3A,$25,$B4,$0E,$00
  DEFB $3A,$25,$B4,$0E,$00,$3A,$25,$B4
  DEFB $0E,$00,$3A,$25,$B4,$0E,$00,$3A
  DEFB $25,$B4,$0E,$00,$3A,$25,$B4,$0E
  DEFB $00,$3A,$25,$B4,$0E,$00,$3A,$25
  DEFB $B4,$0E,$00,$3A,$25,$B4,$0E,$00
  DEFB $3A,$25,$B4,$0E,$00,$3A,$25,$B4
  DEFB $0E,$00,$3A,$25,$B4,$0E,$00,$3A
  DEFB $25,$B4,$0E,$00,$3A,$25,$B4,$0E
  DEFB $00,$3A,$25,$B4,$0E,$00,$3A,$25
  DEFB $B4,$0E,$00,$3A,$25,$B4,$0E,$00
  DEFB $3A,$25,$B4,$0E,$00,$3A,$25,$B4
  DEFB $0E,$00,$3A,$25,$B4,$0E,$00,$3A
  DEFB $25,$B4,$0E,$00,$3A,$25,$B4,$0E
  DEFB $00,$3A,$25,$B4,$0E,$00,$3A,$25
  DEFB $B4,$0E,$00,$3A,$25,$B4,$0E,$00
  DEFB $3A,$25,$B4,$0E,$00,$3A,$25,$B4
  DEFB $0E,$00,$3A,$25,$B4,$0E,$00,$3A
  DEFB $25,$B4,$0E,$00,$3A,$25,$B4,$0E
  DEFB $00,$3A,$25,$B4,$0E,$00,$3A,$25
  DEFB $B4,$0E,$00,$3A,$25,$B4,$0E,$00
  DEFB $3A,$25,$B4,$0E,$00,$3A,$25,$B4
  DEFB $0E,$00,$3A,$25,$B4,$0E,$00,$3A
  DEFB $25,$B4,$0E,$00,$3A,$25,$B4,$0E
  DEFB $00,$3A,$25,$B4,$0E,$00,$3A,$25
  DEFB $B4,$0E,$00,$3A,$25,$B4,$0E,$00
  DEFB $3A,$25,$B4,$0E,$00,$3A,$25,$B4
  DEFB $0E,$00,$3A,$25,$B4,$0E,$00,$3A
  DEFB $25,$B4,$0E,$00,$3A,$25,$B4,$0E
  DEFB $00,$3A,$25,$B4,$0E,$00,$3A,$25
  DEFB $B4,$0E,$00,$3A,$25,$B4,$0E,$00
  DEFB $3A,$25,$B4,$C9,$FF,$FF,$FF,$FF
  DEFB $FF

; Throw a grenade, or keep one flying
;
; Used by the routine at MOVE_GRENADE.
;
; S, D, F and G throw, further along the keyboard throwing further: each key's
; bit is its flight time (2, 4, 8 or 16 frames). The grenade starts at the
; player and moves like anything else, a cell a frame; when the time runs out
; it explodes where it is.
;
; Every frame of the flight, not only the last, the grenade is checked against
; the player's cell and the rescued person's: if it is in either, they are
; blown up.
;
; IX The grenade
; IY The player
THROW_GRENADE:
  LD A,(THROW_TIME)       ; In flight.
  AND A                   ;
  JR NZ,THROW_GRENADE_0   ;
  LD A,(IX+$09)           ; Still exploding.
  AND A                   ;
  RET NZ                  ;
  LD BC,$FDFE             ; A to G: S, D, F or G.
  IN A,(C)                ;
  CPL                     ;
  AND $1E                 ;
  RET Z                   ;
  LD C,A                  ; C = the flight time.
  LD A,(AMMO_LOW)         ; None left, or one fewer.
  AND A                   ;
  RET Z                   ;
  DEC A                   ;
  LD (AMMO_LOW),A         ;
  LD A,C                  ; Launch.
  LD (THROW_TIME),A       ;
  LD (IY+$08),$02         ; The player's throwing pose.
  SET 2,(IX+$07)          ; The grenade moves...
  CALL COPY_POSITION      ; ...from where the player is...
  LD A,$01                ; ...and the count is reprinted.
  LD (GRENADE_EVENTS),A   ;
  LD (IX+$08),$F4         ; In flight it is drawn as frame $F4.
  RET                     ;
THROW_GRENADE_0:
  DEC A                   ; One frame less in the air...
  LD (THROW_TIME),A       ;
  JR NZ,THROW_GRENADE_1   ;
  LD A,$02                ; ...and at the end, bang: explode and stop.
  LD (GRENADE_EVENTS),A   ;
  LD (IX+$09),$05         ;
  RES 2,(IX+$07)          ;
  NOP
THROW_GRENADE_1:
  LD A,(IX+$00)           ; In the player's cell...
  CP (IY+$00)             ;
  JR NZ,THROW_GRENADE_3   ;
  LD A,(IX+$01)           ;
  CP (IY+$01)             ;
  JR NZ,THROW_GRENADE_2   ;
  LD A,(IX+$02)           ;
  CP (IY+$02)             ;
  JR NZ,THROW_GRENADE_2   ;
  LD A,(IY+$09)           ; ...blows the player up.
  AND A                   ;
  RET NZ                  ;
  LD (IY+$09),$05         ;
  LD (IY+$0F),$08         ;
  RET
THROW_GRENADE_2:
  LD A,(IX+$00)           ; In the rescued person's cell...
THROW_GRENADE_3:
  CP (IY+$10)             ;
  RET NZ                  ;
  LD A,(IX+$01)           ;
  CP (IY+$11)             ;
  RET NZ                  ;
  LD A,(IX+$02)           ;
  CP (IY+$12)             ;
  RET NZ                  ;
  LD A,(IY+$19)           ; ...blows them up.
  AND A                   ;
  RET NZ                  ;
  LD (IY+$19),$05         ;
  LD (IY+$1F),$08         ;
  RET

; Unused
L8D94:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF

; Check each ant against an exploding grenade
;
; Used by the routine at MOVE_GRENADE.
GRENADE_BLAST:
  LD A,(IX+$09)
  AND A
  RET Z
  LD L,(IX+$00)
  LD H,(IX+$01)
  LD C,(IX+$02)
  LD IY,ANT1
  CALL BLAST_ANT
  LD IY,ANT2
  CALL BLAST_ANT
  LD IY,ANT3
  CALL BLAST_ANT
  LD IY,ANT4
  CALL BLAST_ANT
  LD IY,ANT5
  CALL BLAST_ANT
  RET

; Unused
L8DCC:
  DEFB $FF,$FF,$FF,$FF

; Count the time down and print it
;
; Used by the routine at GAME_FRAME.
;
; One tick every three frames. The time is big-endian, as the ROM's OUT-NUM-2
; prints it.
COUNT_DOWN_TIME:
  LD HL,TIME_TICKS        ; Every third frame.
  DEC (HL)                ;
  RET NZ                  ;
  LD (HL),$03             ;
  INC HL                  ;
  LD B,(HL)
  INC HL
  LD C,(HL)
  LD A,B                  ; Already zero.
  OR C                    ;
  JR Z,COUNT_DOWN_TIME_0  ;
  DEC (HL)                ; A redundant decrement of the low byte: the next
                          ; three instructions overwrite it.
  DEC BC                  ; One less.
  LD (HL),C               ;
  DEC HL                  ;
  LD (HL),B               ;
COUNT_DOWN_TIME_0:
  LD IY,ERR_NR            ; PRINT AT 19,20;
  LD A,$02                ;
  CALL $1601              ;
  LD A,$16                ;
  RST $10                 ;
  LD A,$13                ;
  RST $10                 ;
  LD A,$14                ;
  RST $10                 ;
  LD HL,TIME              ; The time.
  CALL $1A28              ;
  RET

; Unused
L8DFD:
  DEFB $FF,$FF,$FF

; Run script 1, "NASTY FALL !"
;
; Used by the routine at HANDLE_EVENTS.
PLAY_SCRIPT_ONE:
  LD A,$01

; Run a script, keeping IX
;
; Used by the routines at PRINT_COUNTERS, PARALYSE_ANT, CHECK_RESCUED,
; FINAL_SCRIPT, HANDLE_EVENTS, MOVE_RESCUEE and GRENADE_SOUNDS.
;
; A The script's number
PLAY_SCRIPT:
  LD D,A
  PUSH IX
  CALL RUN_SCRIPT
  POP IX
  RET

; Unused
L8E0B:
  DEFB $FF,$FF

; Run a script: text, sound and colour
;
; Used by the routine at PLAY_SCRIPT.
;
; Every message the machine code shows and every sound it makes is a script in
; SCRIPTS: the Dth record there, counting the $FF that ends each. The first
; byte is a stream to print to (2, the upper screen); then, until $FF:
;
; $80-$FF: a sound -- bits 0-3 a note from TONES, $0F meaning noise, and bits
; 4-6 one less than how many times. $7D: the next byte is an attribute to fill
; the play area with. $7E: the next byte is the low byte of the address of a
; two-byte number, in the variables, to print. Anything else is printed,
; control codes and all.
;
; D The script's number
RUN_SCRIPT:
  LD IY,ERR_NR            ; Find the Dth $FF from SCRIPTS...
  LD HL,SCRIPTS           ;
  LD BC,$0800             ;
  LD A,$FF                ;
RUN_SCRIPT_0:
  CPIR                    ; ...or give up after 2K.
  RET PO                  ;
  DEC D                   ;
  JR NZ,RUN_SCRIPT_0      ;
  PUSH HL                 ; IX = the script.
  POP IX                  ;
  LD A,(IX+$00)           ; Stream 1 or 2, or nothing.
  INC IX                  ;
  DEC A                   ;
  CP $02                  ;
  RET NC                  ;
  INC A                   ;
  CALL $1601              ;
RUN_SCRIPT_1:
  LD A,(IX+$00)           ; The next byte; $FF ends.
  INC IX                  ;
  CP $FF                  ;
  RET Z                   ;
  AND A                   ; A sound?
  JP P,RUN_SCRIPT_4       ;
  LD B,A                  ; D = how many times.
  AND $70                 ;
  RLCA                    ;
  RLCA                    ;
  RLCA                    ;
  RLCA                    ;
  INC A                   ;
  LD D,A                  ;
  LD A,B                  ; E = the note; $0F is noise.
  AND $0F                 ;
  CP $0F                  ;
  JR Z,RUN_SCRIPT_3       ;
RUN_SCRIPT_2:
  PUSH AF                 ; Play the note D times.
  CALL TONE               ;
  POP AF                  ;
  DEC D                   ;
  JR NZ,RUN_SCRIPT_2      ;
  JR RUN_SCRIPT_1         ;
RUN_SCRIPT_3:
  LD B,$00                ; Or the noise.
  CALL NOISE              ;
  DEC D                   ;
  JR NZ,RUN_SCRIPT_3      ;
  JR RUN_SCRIPT_1         ;
RUN_SCRIPT_4:
  CP $7E                  ; $7E: a number.
  JR Z,RUN_SCRIPT_6       ;
  CP $7D                  ; $7D: a colour.
  JR Z,RUN_SCRIPT_5       ;
  RST $10                 ; Print anything else.
  JR RUN_SCRIPT_1         ;
RUN_SCRIPT_5:
  LD A,(IX+$00)             ; Fill the play area with the colour.
  INC IX                    ;
  CALL FILL_PLAY_ATTRIBUTES ;
  JR RUN_SCRIPT_1
RUN_SCRIPT_6:
  LD L,(IX+$00)           ; Print the number whose address has the next byte as
  INC IX                  ; its low byte and $B4 as its high.
  LD H,$B4                ;
  CALL $1A28              ;
  JR RUN_SCRIPT_1

; One frame of play
;
; Used by the routine at PLAY.
GAME_FRAME:
  CALL MOVE_PLAYER        ; The player.
  CALL MOVE_RESCUEE       ; The person to be rescued.
  CALL MOVE_GRENADE       ; The grenade.
  CALL MOVE_ANTS          ; The ants.
  CALL READ_VIEW_KEYS     ; The view keys.
  CALL DRAW_VIEW          ; Draw.
  CALL HANDLE_EVENTS      ; Messages for what happened to the two people...
  CALL GRENADE_SOUNDS     ; ...and to the grenade.
  CALL COUNT_DOWN_TIME    ; The clock.
  RET                     ;

; Unused
L8E9C:
  DEFB $FF,$FF,$FF,$FF

; Have the player and the rescued person both left the city?
;
; Used by the routine at PLAY.
;
; Seen in play. Once both are outside the walls, the rescued person's +D is set
; to 2 -- BASIC's w, which line 70 reads as success -- "CONGRATULATIONS !" is
; shown, and the game stops next frame.
CHECK_RESCUED:
  LD HL,PLAYER            ; The player is inside if both x and y have bit 7
  LD A,(HL)               ; set...
  INC HL                  ;
  AND (HL)                ;
  RET M                   ;
  LD L,$90                ; ...and the same for the rescued person.
  LD A,(HL)               ;
  INC HL                  ;
  AND (HL)                ;
  RET M                   ;
  LD A,(RESCUEE_STATE)    ; Already done.
  CP $02                  ;
  RET Z                   ;
  LD A,$02                ; Rescued.
  LD (RESCUEE_STATE),A    ;
  LD A,$0D                ;
  CALL PLAY_SCRIPT        ;
  LD A,$01                ; Stop after this frame.
  LD (FRAMES_LEFT),A      ;
  LD (TIME_TICKS),A       ;
  RET

; Unused
L8EC6:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF

; Stop the game when time or either energy runs out
;
; Used by the routine at PLAY.
;
; Five frames later, so the last message is seen. Seen in play for the time.
CHECK_GAME_OVER:
  LD HL,PLAYER_ENERGY_LOW ; Either energy at zero...
  LD A,(HL)               ;
  AND A                   ;
  JR Z,CHECK_GAME_OVER_0  ;
  LD L,$34                ;
  LD A,(HL)               ;
  AND A                   ;
  JR Z,CHECK_GAME_OVER_0  ;
  LD L,$36                ; ...or the time.
  LD A,(HL)               ;
  INC HL                  ;
  OR (HL)                 ;
  RET NZ                  ;
CHECK_GAME_OVER_0:
  LD A,(FRAMES_LEFT)      ; Only once.
  CP $FF                  ;
  RET NZ                  ;
  LD A,$05                ; Five more frames.
  LD (FRAMES_LEFT),A      ;
  LD (TIME_TICKS),A       ;
  RET

; The ending (USR 36594)
;
; Script 17, "YOU ARE A REAL HERO", called from BASIC line 3600 after the tenth
; rescue. Seen in play, with BASIC's fin set to 1.
FINAL_SCRIPT:
  DI
  LD A,$11
  CALL PLAY_SCRIPT
  EI
  RET

; Unused
L8EFA:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF

; React to what happened to the player and the rescued person
;
; Used by the routine at GAME_FRAME.
;
; Reads and clears the two event bytes (+F). A step is a click; a bad fall,
; "NASTY FALL !" or "HELP! I FELL!"; blown up, energy to 0 with "SILLY! YOU
; BLEW YOURSELF UP !" or "HOW COULD YOU ?"; bitten, an energy point off with
; "BITTEN!" or "THEY GOT ME", or when it reaches 0, "EATEN ALIVE" or "IVE BEEN
; EATEN ALIVE". All seen in play.
HANDLE_EVENTS:
  XOR A                   ; E = the player's event, D = the other's, both
  LD HL,PLAYER_EVENT      ; cleared.
  LD E,(HL)               ;
  LD (HL),A               ;
  LD L,$9F                ;
  LD D,(HL)               ;
  LD (HL),A               ;
  LD A,D                  ; Nothing happened.
  OR E                    ;
  RET Z                   ;
  DEC A                   ; Only a step: a click.
  JR NZ,HANDLE_EVENTS_0   ;
  LD B,$05                ;
  CALL NOISE              ;
  RET
HANDLE_EVENTS_0:
  LD A,$02                ; The player's bad fall...
  CP E                    ;
  JR NZ,HANDLE_EVENTS_1   ;
  CALL PLAY_SCRIPT_ONE    ;
  LD A,$02                ;
HANDLE_EVENTS_1:
  CP D                    ; ...or theirs.
  JR NZ,HANDLE_EVENTS_2   ;
  CALL PLAY_SCRIPT        ;
  RET
HANDLE_EVENTS_2:
  PUSH DE                 ; The player blown up: energy 0.
  LD HL,PLAYER_ENERGY_LOW ;
  LD A,E                  ;
  CP $08                  ;
  JR NZ,HANDLE_EVENTS_3   ;
  LD (HL),$00             ;
  LD A,$06                ;
  CALL PLAY_SCRIPT        ;
  JR HANDLE_EVENTS_5      ;
HANDLE_EVENTS_3:
  CP $04                  ; Bitten: a point off, and which message.
  JR NZ,HANDLE_EVENTS_6   ;
  LD A,(HL)               ;
  AND A                   ;
  JR Z,HANDLE_EVENTS_5    ;
  DEC (HL)                ;
  LD A,$0E                ;
  JR Z,HANDLE_EVENTS_4    ;
  LD A,$07                ;
HANDLE_EVENTS_4:
  CALL PLAY_SCRIPT        ;
HANDLE_EVENTS_5:
  LD A,$08                ; Reprint the player's energy.
  CALL PLAY_SCRIPT        ;
HANDLE_EVENTS_6:
  POP DE                   ; The same for the rescued person.
  LD HL,RESCUEE_ENERGY_LOW ;
  LD A,D                   ;
  CP $08                   ;
  JR NZ,HANDLE_EVENTS_7    ;
  LD (HL),$00              ;
  LD A,$09                 ;
  CALL PLAY_SCRIPT         ;
  JR HANDLE_EVENTS_9       ;
HANDLE_EVENTS_7:
  CP $04                   ;
  JR NZ,HANDLE_EVENTS_10   ;
  LD A,(HL)                ;
  AND A                    ;
  JR Z,HANDLE_EVENTS_9     ;
  DEC (HL)                 ;
  LD A,$0F                 ;
  JR Z,HANDLE_EVENTS_8     ;
  LD A,$0A                 ;
HANDLE_EVENTS_8:
  CALL PLAY_SCRIPT         ;
HANDLE_EVENTS_9:
  LD A,$0B                 ;
  CALL PLAY_SCRIPT         ;
HANDLE_EVENTS_10:
  RET

; Unused
L8F7A:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF

; The person to be rescued: wait, or follow
;
; Used by the routine at GAME_FRAME.
;
; Waiting, they drive the scanner, and are found when the player comes within
; three cells at the same height: "MY HERO!". After that they follow the
; player.
MOVE_RESCUEE:
  LD IX,RESCUEE
  LD IY,PLAYER
  LD A,(IX+$0D)           ; Found yet?
  AND A                   ;
  JR Z,MOVE_RESCUEE_0     ;
  CALL SHARE_CELL         ; Following: stand clear, follow, move, animate.
  CALL FOLLOW_PLAYER      ;
  CALL MOVE_OR_RESPAWN    ;
  CALL CHOOSE_FRAME       ;
  RET                     ;
MOVE_RESCUEE_0:
  LD L,(IX+$00)           ; Waiting: how far is the player?
  LD H,(IX+$01)           ;
  LD E,(IY+$00)           ;
  LD D,(IY+$01)           ;
  CALL DISTANCE           ;
  LD C,A                  ;
  CP (IX+$0E)             ; Green if closer than last frame.
  LD (IX+$0E),A           ;
  CALL SCANNER            ;
  LD A,C                  ; Within three cells at the same height...
  CP $04                  ;
  RET NC                  ;
  LD A,(IX+$02)           ;
  CP (IY+$02)             ;
  RET NZ                  ;
  LD (IX+$0D),$01         ; ...found: "MY HERO!". The scanner goes red, the
  CALL SCANNER            ; flags left from the height comparison.
  LD A,$0C                ;
  CALL PLAY_SCRIPT        ;
  RET

; Unused
L8FCC:
  DEFB $FF,$FF,$FF,$FF

; Show and sound what the grenade did
;
; Used by the routine at GAME_FRAME.
;
; GRENADE_EVENTS: bit 0 thrown (reprint the count), bit 1 exploded (a bang),
; bit 2 hit an ant ("GOOD SHOT!").
GRENADE_SOUNDS:
  LD HL,GRENADE_EVENTS
  LD A,(HL)
  AND A
  RET Z
  PUSH AF
  LD (HL),$00
  BIT 0,A
  JR Z,GRENADE_SOUNDS_0
  LD A,$04
  JR GRENADE_SOUNDS_1
GRENADE_SOUNDS_0:
  BIT 1,A
  JR Z,GRENADE_SOUNDS_2
  LD A,$05
GRENADE_SOUNDS_1:
  CALL PLAY_SCRIPT
GRENADE_SOUNDS_2:
  POP AF
  BIT 2,A
  RET Z
  LD A,$03
  CALL PLAY_SCRIPT
  RET

; Unused
L8FF4:
  DEFB $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF
  DEFB $FF,$FF,$FF,$FF

; Scripts
;
; The $FF that ends a script zero. RUN_SCRIPT finds script n by counting $FF
; bytes from here, so the seventeen that follow are numbered from 1; see
; RUN_SCRIPT for their format, and the scripts page for what each says and
; when. The build generates their blocks, since their titles are their words.
SCRIPTS:
  DEFB $FF

; Script 1: NASTY FALL !
SCRIPT1:
  DEFB $02
  DEFB $16
  DEFB $0F
  DEFB $0A
  DEFM "NASTY FALL !"
  DEFB $8E
  DEFB $8D
  DEFB $8B
