; Where the load finishes
;
; The loader in the BASIC line leaves LD-BYTES's return address pointing here.
; A failed load (carry clear) or a short one (DE not zero) resets the machine.
LOADED:
  JP NC,$0000             ; Carry clear: a tape error.
  LD A,D                  ; Bytes left over: a short load.
  OR E                    ;
  JP NZ,$0000             ;
  LD A,$98                ; The interrupt vectors at INTERRUPT_VECTORS: every
  LD I,A                  ; one points to INTERRUPT.
  IM 2                    ;
  DI                      ; Run the BASIC.
  JP RESTART_BASIC        ;

; Unused
;
; Zeros, $02 filler, and just before INTERRUPT a stray copy of the interrupt
; set-up.
L9712:
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
  DEFB $00,$00,$00,$00,$00,$00,$00,$00
