; The interrupt routine: no BREAK
;
; Passes the interrupt to the ROM unless an error is pending -- BREAK, most
; likely -- and if one is, restarts the BASIC program instead of letting it
; stop.
INTERRUPT:
  DI
  PUSH AF
  LD A,(ERR_NR)           ; No error: the ROM's interrupt routine.
  CP $FF                  ;
  JR Z,RESTART_BASIC_0    ;

; Type RUN and run it
;
; Used by the routine at LOADED.
;
; Clears the error, resets the stack from ERR_SP, puts RUN and ENTER in the
; edit line and jumps into the ROM's line executor. This is also how the game
; starts after loading, since the tape's program header has no auto-run line.
RESTART_BASIC:
  LD A,$FF                ; No error.
  LD (ERR_NR),A           ;
  LD SP,(ERR_SP)          ; The stack BASIC keeps.
  LD HL,(E_LINE)          ; RUN, ENTER into the edit line.
  LD A,$F7                ;
  LD (HL),A               ;
  INC HL                  ;
  LD A,$0D                ;
  LD (HL),A               ;
  EI
  JP $12B4                ; The ROM's statement loop, as if ENTER had been
                          ; pressed.
; This entry point is used by the routine at INTERRUPT.
RESTART_BASIC_0:
  POP AF                  ; The ROM's own interrupt routine.
  JP $0038                ;

