; Game variables
;
; BASIC sets most of these at the start of each level (lines 200-220, and 750
; for the time). The two-byte counts are big-endian, for the ROM's OUT-NUM-2,
; and the code only ever touches their low bytes.
VIEW_ORIGIN:
  DEFB $00,$00            ; The x and y the view is drawn from
VIEW:
  DEFB $00                ; Which of the four views, 0-3
  DEFB $00,$00,$00,$00,$00 ; Set to 1 by BASIC; not used by the machine code
RANDOM_BITS:
  DEFB $00,$00,$00        ; The random number generator, 32 bits big-endian:
                          ; the first byte is left in SEED for BASIC...
RANDOM_LOW:
  DEFB $00                ; ...and this is where RANDOM shifts in the new bit
BORDER:
  DEFB $00                ; The border colour, for the sound routines
GRENADE_EVENTS:
  DEFB $00                ; What the grenade did, for GRENADE_SOUNDS
THROW_TIME:
  DEFB $00                ; Frames of flight left
AMMO:
  DEFB $00                ; Grenades left: the high byte, always 0...
AMMO_LOW:
  DEFB $00                ; ...and the low
PLAYER_ENERGY:
  DEFB $00                ; The player's energy: the high byte, always 0...
PLAYER_ENERGY_LOW:
  DEFB $00                ; ...and the low
RESCUEE_ENERGY:
  DEFB $00                ; The rescued person's energy: the high byte, always
                          ; 0...
RESCUEE_ENERGY_LOW:
  DEFB $00                ; ...and the low
TIME_TICKS:
  DEFB $00                ; Frames to the next tick of the clock
TIME:
  DEFB $00,$00            ; The time
FRAMES_LEFT:
  DEFB $00                ; Frames to run; $FF, until the game says stop (see
                          ; PLAY)
  DEFB $00,$00,$00,$00,$00,$00,$00,$00 ; Unused
  DEFB $00,$00,$00,$00,$00,$00,$00,$00 ;
  DEFB $00,$00,$00,$00,$00,$00         ;
CLEAR_PHASE:
  DEFB $00                ; Which rows CLEAR_BUFFER_ROWS clears next

; Sprite list
;
; Three bytes an object, in the order PROJECT_SPRITES meets them, the last
; object first: the place in PLANES -- turned into a distance once sorted --
; and the frame.
SPRITE_LIST:
  DEFB $00,$00,$00        ; The ants, the fifth first
  DEFB $00,$00,$00        ;
  DEFB $00,$00,$00        ;
  DEFB $00,$00,$00        ;
  DEFB $00,$00,$00        ;
  DEFB $00,$00,$00        ; The grenade
RESCUEE_SPRITE:
  DEFB $00,$00,$00        ; The rescued person
PLAYER_SPRITE:
  DEFB $00,$00,$00        ; The player
  DEFB $00                ; End marker: a count to a ninth sprite too big ever
                          ; to be reached...
SPRITE_LIST_END:
  DEFB $00                ; ...its high byte set by PLAY
  DEFB $00,$00,$00,$00,$00,$00,$00,$00 ; Unused
  DEFB $00,$00,$00,$00,$00,$00,$00,$00 ;
  DEFB $00,$00,$00,$00,$00,$00         ;

